) as p(province_code, province_name, region) on p.province_code = v.province_code
on conflict (istat_code) do update set
  name = excluded.name, province_code = excluded.province_code,
  province_name = excluded.province_name, region = excluded.region, caps = excluded.caps,
  climate_zone = excluded.climate_zone, climate_zone_source = excluded.climate_zone_source;
